@ VPy — PiTrex target (ARM32 / ARMv6 / Pi Zero)
@ Game: DRAW_VECTOR
@ Generated by vpy_codegen pitrex backend
@ Assemble: arm-none-eabi-as -march=armv6 -mfpu=vfp -mfloat-abi=hard game.s -o game.o
@ Link:     arm-none-eabi-gcc -march=armv6 -mfpu=vfp -mfloat-abi=hard -nostartfiles
@             -L$(PITREX_SDK)/lib game.o -lbaremetal -lvectrexInterface -luspi -o game.elf
@ Binary:   arm-none-eabi-objcopy -O binary game.elf game.img

.arch armv6
.fpu vfp
.syntax unified

@ --- PiTrex SDK externals ---
.extern vectrexinit
.extern v_init
.extern v_setRefresh
.extern v_WaitRecal
.extern v_readButtons
.extern v_readJoystick1Analog
.extern v_directDraw32
.extern v_directMove32
.extern v_setBrightness
.extern v_setScale
.extern v_printString
.extern v_printStringRaster
.extern v_writePSG
.extern v_doSound
.extern currentJoy1X
.extern currentJoy1Y
.extern currentButtonState
.extern currentJoy2X
.extern currentJoy2Y
.extern __aeabi_idiv
.extern __aeabi_idivmod
.extern RPI_AuxUartInit
.extern RPI_AuxUartWrite

.section .bss
.align 2
.equ VAR_ARG0, 0x0010000C
.equ VAR_ARG1, 0x00100010
.equ VAR_ARG2, 0x00100014
.equ VAR_ARG3, 0x00100018
.equ VAR_ARG4, 0x0010001C
.equ RESULT, 0x00100020
.equ BEEP_FRAMES_LEFT, 0x00100024
.equ RAND_SEED, 0x00100028
.equ CAMERA_X, 0x0010002C
.equ CAMERA_Y, 0x00100030
.equ TEXT_SIZE, 0x00100034
.equ PITREX_TEXT_SIZE, 0x00100034
.equ PSG_MUSIC_PTR, 0x00100038
.equ PSG_MUSIC_START, 0x0010003C
.equ PSG_IS_PLAYING, 0x00100040
.equ PSG_DELAY_FRAMES, 0x00100044
.equ PSG_SFX_PTR, 0x00100048
.equ PSG_SFX_ACTIVE, 0x0010004C
.equ PSG_SFX_DELAY, 0x00100050
.equ LEVEL_DATA_PTR, 0x00100054
.equ LEVEL_GP_COUNT, 0x00100058
.equ LEVEL_GP_BUF, 0x0010005C
.equ SCROLL_LIMIT_LEFT, 0x0010015C
.equ SCROLL_LIMIT_RIGHT, 0x00100160
.equ SCROLL_LIMIT_TOP, 0x00100164
.equ SCROLL_LIMIT_BOTTOM, 0x00100168

PITREX_CUR_X: .space 4
PITREX_CUR_Y: .space 4

.section .rodata
.align 2

.section .text
.align 2

@ ================================================================
@ PiTrex ARM32 builtins
@ ================================================================

@ pitrex_wait_recal() — frame sync via v_WaitRecal(), then fix scale=127
.global pitrex_wait_recal
.type pitrex_wait_recal, %function
pitrex_wait_recal:
    push    {lr}
    bl      v_WaitRecal
    mov     r0, #127
    bl      v_setScale
    pop     {pc}
    .ltorg

@ pitrex_set_intensity(r0=brightness 0-127)
.global pitrex_set_intensity
.type pitrex_set_intensity, %function
pitrex_set_intensity:
    push    {lr}
    bl      v_setBrightness
    pop     {pc}
    .ltorg

@ pitrex_move(r0=x, r1=y) — move beam, no draw
.global pitrex_move
.type pitrex_move, %function
pitrex_move:
    push    {r4, lr}
    mov     r4, #127
    mul     r2, r0, r4          @ r2 = x*127 (Rd≠Rm)
    ldr     r4, =PITREX_CUR_X
    str     r2, [r4]            @ PITREX_CUR_X = x*127
    mov     r4, #127
    mul     r2, r1, r4          @ r2 = y*127 (Rd≠Rm)
    ldr     r4, =PITREX_CUR_Y
    str     r2, [r4]            @ PITREX_CUR_Y = y*127
    bl      v_directMove32
    pop     {r4, pc}
    .ltorg

@ pitrex_draw_line(r0=x0, r1=y0, r2=x1, r3=y1, [sp+0]=brightness)
.global pitrex_draw_line
.type pitrex_draw_line, %function
pitrex_draw_line:
    push    {r4, lr}
    ldr     r4, [sp, #8]        @ brightness
    mov     r12, #127
    mul     r0, r0, r12         @ x0 * 127
    mul     r1, r1, r12         @ y0 * 127
    mul     r2, r2, r12         @ x1 * 127
    mul     r3, r3, r12         @ y1 * 127
    push    {r4}               @ brightness as 5th arg
    bl      v_directDraw32
    add     sp, sp, #4
    pop     {r4, pc}
    .ltorg

@ pitrex_draw_line_rel(r0=dx, r1=dy, r2=brightness)
.global pitrex_draw_line_rel
.type pitrex_draw_line_rel, %function
pitrex_draw_line_rel:
    push    {r4, r5, r6, r7, lr}
    mov     r4, #127
    mul     r4, r0, r4          @ r4 = dx * 127
    mov     r5, #127
    mul     r5, r1, r5          @ r5 = dy * 127
    mov     r6, r2              @ r6 = brightness
    ldr     r7, =PITREX_CUR_X
    ldr     r0, [r7]            @ r0 = cur_x
    ldr     r12, =PITREX_CUR_Y
    ldr     r1, [r12]           @ r1 = cur_y
    add     r2, r0, r4          @ r2 = new_x
    add     r3, r1, r5          @ r3 = new_y
    push    {r6}               @ brightness as 5th arg
    bl      v_directDraw32
    add     sp, sp, #4
    ldr     r1, =PITREX_CUR_X
    ldr     r2, [r1]
    add     r2, r2, r4
    str     r2, [r1]            @ PITREX_CUR_X += dx*100
    ldr     r1, =PITREX_CUR_Y
    ldr     r2, [r1]
    add     r2, r2, r5
    str     r2, [r1]            @ PITREX_CUR_Y += dy*100
    pop     {r4, r5, r6, r7, pc}
    .ltorg

@ pitrex_draw_vector(r0=asset_ptr, r1=ox, r2=oy)
.global pitrex_draw_vector
.type pitrex_draw_vector, %function
pitrex_draw_vector:
    push    {r4, r5, r6, r7, r8, r9, r10, r11, lr}
    mov     r4, r0              @ asset header ptr
    mov     r10, r1             @ ox (unscaled)
    mov     r11, r2             @ oy (unscaled)
    ldr     r5, [r4], #4        @ path_count
    mov     r8, #0
dv_path_loop:
    cmp     r8, r5
    bge     dv_done
    ldr     r9, [r4], #4        @ r9 = path data ptr
    add     r9, r9, #1          @ skip intensity byte
    ldrsb   r1, [r9], #1        @ r1 = y_start (i8)
    ldrsb   r0, [r9], #1        @ r0 = x_start (i8)
    add     r9, r9, #2          @ skip 2 hdr padding bytes
    add     r0, r0, r10         @ r0 = x_start + ox (raw)
    add     r1, r1, r11         @ r1 = y_start + oy (raw)
    mov     r3, #127
    mul     r2, r0, r3          @ r2 = raw_tx*127
    ldr     r3, =PITREX_CUR_X
    str     r2, [r3]            @ PITREX_CUR_X = raw_tx*127
    mov     r3, #127
    mul     r2, r1, r3          @ r2 = raw_ty*127
    ldr     r3, =PITREX_CUR_Y
    str     r2, [r3]            @ PITREX_CUR_Y = raw_ty*127
    push    {r0, r1}
    ldr     r0, =.Lstr_dv_p
    bl      vpy_uart_puts
    mov     r0, r8
    bl      vpy_uart_print_int
    ldr     r0, =.Lstr_tgt
    bl      vpy_uart_puts
    ldr     r0, [sp, #0]
    bl      vpy_uart_print_int
    mov     r0, #','
    bl      RPI_AuxUartWrite
    ldr     r0, [sp, #4]
    bl      vpy_uart_print_int
    ldr     r0, =.Lstr_crlf
    bl      vpy_uart_puts
    pop     {r0, r1}
    bl      v_directMove32
    b       dv_after_pool
    .ltorg
dv_after_pool:
dv_seg_loop:
    ldrb    r0, [r9], #1        @ marker (0xFF=draw, 0x02=end)
    cmp     r0, #2
    beq     dv_seg_done
    ldrsb   r1, [r9], #1        @ dy
    ldrsb   r0, [r9], #1        @ dx
    mov     r2, #127            @ full brightness
    push    {r4, r5, r6, r7, r8, r9}
    bl      pitrex_draw_line_rel
    pop     {r4, r5, r6, r7, r8, r9}
    b       dv_seg_loop
dv_seg_done:
    add     r8, r8, #1
    b       dv_path_loop
dv_done:
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, pc}
    .ltorg

@ pitrex_draw_vector_ex(r0=asset_ptr, r1=ox, r2=oy, r3=mirror, [sp]=intensity)
.global pitrex_draw_vector_ex
.type pitrex_draw_vector_ex, %function
pitrex_draw_vector_ex:
    push    {r4, r5, r6, r7, r8, r9, lr}    @ 28 bytes
    mov     r4, r0              @ asset header ptr
    mov     r5, r1              @ ox
    mov     r6, r2              @ oy
    mov     r7, r3              @ mirror flag
    ldr     r8, [sp, #28]       @ intensity (5th arg)
    ldr     r9, [r4], #4        @ path_count
    push    {r9}                @ [sp+0] = path_count
    mov     r9, #0
    push    {r9}                @ [sp+0] = path_idx, [sp+4] = path_count
dvex_path_loop:
    ldr     r0, [sp]            @ path_idx
    ldr     r1, [sp, #4]        @ path_count
    cmp     r0, r1
    bge     dvex_done
    ldr     r9, [r4], #4        @ r9 = path data ptr
    add     r9, r9, #1          @ skip intensity byte
    ldrsb   r1, [r9], #1        @ r1 = y_start (i8)
    ldrsb   r0, [r9], #1        @ r0 = x_start (i8)
    add     r9, r9, #2          @ skip 2 hdr padding bytes
    cmp     r7, #1
    it      eq
    rsbeq   r0, r0, #0          @ mirror dx
    add     r0, r0, r5          @ r0 = x_start + ox (raw)
    add     r1, r1, r6          @ r1 = y_start + oy (raw)
    mov     r12, #127
    mul     r2, r0, r12         @ r2 = raw_tx*127
    ldr     r3, =PITREX_CUR_X
    str     r2, [r3]            @ PITREX_CUR_X = raw_tx*127
    mov     r12, #127
    mul     r2, r1, r12         @ r2 = raw_ty*127
    ldr     r3, =PITREX_CUR_Y
    str     r2, [r3]            @ PITREX_CUR_Y = raw_ty*127
    bl      v_directMove32
dvex_seg_loop:
    ldrb    r0, [r9], #1
    cmp     r0, #2
    beq     dvex_seg_done
    ldrsb   r1, [r9], #1        @ dy
    ldrsb   r0, [r9], #1        @ dx
    cmp     r7, #1
    it      eq
    rsbeq   r0, r0, #0
    mov     r2, r8              @ intensity
    push    {r4, r5, r6, r7, r8, r9}
    bl      pitrex_draw_line_rel
    pop     {r4, r5, r6, r7, r8, r9}
    b       dvex_seg_loop
dvex_seg_done:
    ldr     r0, [sp]
    add     r0, r0, #1
    str     r0, [sp]            @ path_idx++
    b       dvex_path_loop
dvex_done:
    add     sp, sp, #8          @ pop path_idx + path_count
    pop     {r4, r5, r6, r7, r8, r9, pc}
    .ltorg

@ pitrex_j1_x() → r0 = X axis (-127..127)
.global pitrex_j1_x
.type pitrex_j1_x, %function
pitrex_j1_x:
    ldr     r1, =currentJoy1X
    ldrsb   r0, [r1]
    bx      lr
    .ltorg

@ pitrex_j1_y() → r0 = Y axis (-127..127)
.global pitrex_j1_y
.type pitrex_j1_y, %function
pitrex_j1_y:
    ldr     r1, =currentJoy1Y
    ldrsb   r0, [r1]
    bx      lr
    .ltorg

@ pitrex_j1_btn1() → r0=1 if pressed, 0 otherwise (bit 0)
.global pitrex_j1_btn1
.type pitrex_j1_btn1, %function
pitrex_j1_btn1:
    ldr     r1, =currentButtonState
    ldr     r0, [r1]
    lsr     r0, r0, #0
    and     r0, r0, #1
    bx      lr
    .ltorg

@ pitrex_j1_btn2() → r0=1 if pressed, 0 otherwise (bit 1)
.global pitrex_j1_btn2
.type pitrex_j1_btn2, %function
pitrex_j1_btn2:
    ldr     r1, =currentButtonState
    ldr     r0, [r1]
    lsr     r0, r0, #1
    and     r0, r0, #1
    bx      lr
    .ltorg

@ pitrex_j1_btn3() → r0=1 if pressed, 0 otherwise (bit 2)
.global pitrex_j1_btn3
.type pitrex_j1_btn3, %function
pitrex_j1_btn3:
    ldr     r1, =currentButtonState
    ldr     r0, [r1]
    lsr     r0, r0, #2
    and     r0, r0, #1
    bx      lr
    .ltorg

@ pitrex_j1_btn4() → r0=1 if pressed, 0 otherwise (bit 3)
.global pitrex_j1_btn4
.type pitrex_j1_btn4, %function
pitrex_j1_btn4:
    ldr     r1, =currentButtonState
    ldr     r0, [r1]
    lsr     r0, r0, #3
    and     r0, r0, #1
    bx      lr
    .ltorg

@ pitrex_print_text(r0=x, r1=y, r2=str_ptr)
.global pitrex_print_text
.type pitrex_print_text, %function
pitrex_print_text:
    push    {r4, r5, r6, lr}
    mov     r4, r0
    mov     r5, r1
    mov     r6, r2
    mov     r0, #0
    mov     r1, #0
    bl      v_directMove32
    mov     r0, r4              @ VPy_x
    mov     r1, r5              @ VPy_y
    mov     r2, r6              @ str_ptr
    ldr     r3, =PITREX_TEXT_SIZE
    ldr     r3, [r3]
    cmp     r3, #0
    it eq
    moveq   r3, #5
    sub     r1, r1, #8          @ baseline = top - cap_height (VPy units)
    mov     r12, #127
    mul     r0, r0, r12          @ r0  = x*127
    asr     r0, r0, #7           @ r0  = x*127/128 (sign-preserving)
    mul     r1, r1, r12          @ r1  = y*127
    asr     r1, r1, #7           @ r1  = y*127/128 (sign-preserving)
    mov     r12, #0x50
    push    {r12}
    bl      v_printString
    add     sp, sp, #4
    pop     {r4, r5, r6, pc}
    .ltorg

@ pitrex_draw_rect(r0=x, r1=y, r2=w, r3=h) 5th=[sp]=brightness
.global pitrex_draw_rect
.type pitrex_draw_rect, %function
pitrex_draw_rect:
    push    {r4, r5, r6, r7, lr}
    mov     r4, r0          @ x (left)
    mov     r5, r1          @ y (bottom)
    mov     r6, r2          @ w
    mov     r7, r3          @ h
    mov     r0, #127
    mul     r4, r4, r0
    mul     r5, r5, r0
    mul     r6, r6, r0
    mul     r7, r7, r0
    mov     r0, r4
    mov     r1, r5
    add     r2, r4, r6
    mov     r3, r5
    ldr     r12, [sp, #20]
    push    {r12}
    bl      v_directDraw32
    add     sp, sp, #4
    add     r0, r4, r6
    mov     r1, r5
    add     r2, r4, r6
    add     r3, r5, r7
    ldr     r12, [sp, #20]
    push    {r12}
    bl      v_directDraw32
    add     sp, sp, #4
    add     r0, r4, r6
    add     r1, r5, r7
    mov     r2, r4
    add     r3, r5, r7
    ldr     r12, [sp, #20]
    push    {r12}
    bl      v_directDraw32
    add     sp, sp, #4
    mov     r0, r4
    add     r1, r5, r7
    mov     r2, r4
    mov     r3, r5
    ldr     r12, [sp, #20]
    push    {r12}
    bl      v_directDraw32
    add     sp, sp, #4
    pop     {r4, r5, r6, r7, pc}

@ pitrex_draw_filled_rect(r0=x, r1=y, r2=w, r3=h, [sp+0]=brightness)
.global pitrex_draw_filled_rect
.type pitrex_draw_filled_rect, %function
pitrex_draw_filled_rect:
    push    {r4, r5, r6, r7, r8, r9, lr}
    mov     r4, r0          @ x (left)
    mov     r5, r1          @ y (bottom)
    mov     r6, r2          @ w
    mov     r7, r3          @ h
    ldr     r8, [sp, #28]   @ brightness ([sp+7regs*4])
    push    {r8}            @ brightness as 5th arg
    bl      pitrex_draw_rect
    add     sp, sp, #4
    mov     r9, #127
    mul     r4, r4, r9      @ x_s
    mul     r5, r5, r9      @ y_s (bottom)
    mul     r6, r6, r9      @ w_s
    mul     r7, r7, r9      @ h_s
    add     r9, r9, r9, lsl #1   @ scan step = 3 * 127 = 381
    add     r0, r5, r9      @ scan_y = y + step
.Lfill_loop:
    add     r1, r5, r7      @ top = y_s + h_s
    cmp     r0, r1
    bge     .Lfill_done     @ exit when scan_y >= top
    mov     r1, r0          @ y0 = scan_y
    add     r2, r4, r6      @ x1 = x_s + w_s
    mov     r3, r0          @ y1 = scan_y
    push    {r0}            @ save scan_y for after the call
    mov     r0, r4          @ x0 = x_s
    push    {r8}            @ brightness as 5th arg ([sp+0])
    bl      v_directDraw32
    add     sp, sp, #4      @ pop brightness
    pop     {r0}            @ restore scan_y
    add     r0, r0, r9      @ scan_y += step
    b       .Lfill_loop
.Lfill_done:
    pop     {r4, r5, r6, r7, r8, r9, pc}
    .ltorg

@ pitrex_draw_polygon(r0=n, r1=intensity, r2=x0, r3=y0, stack=x1,y1,x2,y2,...)
.global pitrex_draw_polygon
.type pitrex_draw_polygon, %function
pitrex_draw_polygon:
    mov     r12, sp
    push    {r4, r5, r6, r7, r8, r9, r10, r11, lr}
    mov     r4, r0          @ n
    mov     r5, #127        @ scale
    mov     r6, r1          @ brightness
    mul     r7, r2, r5      @ x0_s
    mul     r8, r3, r5      @ y0_s
    ldr     r0, [r12, #0]   @ x1 raw
    mul     r9, r0, r5      @ x1_s
    ldr     r0, [r12, #4]   @ y1 raw
    mul     r10, r0, r5     @ y1_s
    push    {r9, r10}       @ save v1 endpoint (cur_x, cur_y)
    mov     r0, r7
    mov     r1, r8
    mov     r2, r9
    mov     r3, r10
    push    {r6}            @ brightness ([sp+0])
    bl      v_directDraw32
    add     sp, sp, #4
    pop     {r9, r10}       @ r9=cur_x=x1_s, r10=cur_y=y1_s
    mov     r11, #2
.Lpoly_loop:
    cmp     r11, r4
    bge     .Lpoly_close
    mov     r0, r11, lsl #1 @ 2k
    sub     r0, r0, #2      @ 2k-2
    lsl     r0, r0, #2      @ (2k-2)*4
    add     r0, r0, #36     @ + callee-save frame (9*4)
    ldr     r2, [sp, r0]    @ xk raw (sp-relative, avoids clobbered r12)
    mul     r0, r2, r5      @ xk_s → r0  (Rd=r0 != Rm=r2)
    mov     r1, r11, lsl #1 @ 2k
    sub     r1, r1, #1      @ 2k-1
    lsl     r1, r1, #2      @ (2k-1)*4
    add     r1, r1, #36     @ + callee-save frame
    ldr     r2, [sp, r1]    @ yk raw (sp-relative)
    mul     r1, r2, r5      @ yk_s → r1  (Rd=r1 != Rm=r2)
    push    {r0, r1}        @ save new xk_s, yk_s
    mov     r2, r0
    mov     r3, r1
    mov     r0, r9
    mov     r1, r10
    push    {r6}            @ brightness
    bl      v_directDraw32
    add     sp, sp, #4
    pop     {r9, r10}       @ r9=xk_s, r10=yk_s
    add     r11, r11, #1
    b       .Lpoly_loop
.Lpoly_close:
    mov     r0, r9
    mov     r1, r10
    mov     r2, r7
    mov     r3, r8
    push    {r6}            @ brightness
    bl      v_directDraw32
    add     sp, sp, #4
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, pc}
    .ltorg

@ pitrex_draw_circle(r0=cx, r1=cy, r2=diameter, r3=brightness)
.global pitrex_draw_circle
.type pitrex_draw_circle, %function
pitrex_draw_circle:
    push    {r4, r5, r6, r7, lr}
    mov     r4, r0          @ cx
    mov     r5, r1          @ cy
    asr     r6, r2, #1      @ radius = diameter/2
    mov     r7, r3          @ brightness
    mov     r0, #127
    mul     r4, r4, r0
    mul     r5, r5, r0
    mul     r6, r6, r0
    ldr     r0, =1024
    mul     r0, r0, r6
    asr     r0, r0, #10
    add     r0, r0, r4
    mov     r1, #0
    mul     r1, r1, r6
    asr     r1, r1, #10
    add     r1, r1, r5
    ldr     r2, =946
    mul     r2, r2, r6
    asr     r2, r2, #10
    add     r2, r2, r4
    ldr     r3, =392
    mul     r3, r3, r6
    asr     r3, r3, #10
    add     r3, r3, r5
    push    {r7}
    bl      v_directDraw32
    add     sp, sp, #4
    ldr     r0, =946
    mul     r0, r0, r6
    asr     r0, r0, #10
    add     r0, r0, r4
    ldr     r1, =392
    mul     r1, r1, r6
    asr     r1, r1, #10
    add     r1, r1, r5
    ldr     r2, =724
