@ pitrex_update_buttons()
.global pitrex_update_buttons
.type pitrex_update_buttons, %function
pitrex_update_buttons:
    push    {lr}
    bl      v_readButtons
    bl      v_readJoystick1Analog
    pop     {pc}

@ pitrex_debug_print(r0=value)
.global pitrex_debug_print
.type pitrex_debug_print, %function
pitrex_debug_print:
    push    {lr}
    bl      pitrex_print_number
    pop     {pc}

@ pitrex_debug_print_labeled(r0=label_ptr, r1=value)
.global pitrex_debug_print_labeled
.type pitrex_debug_print_labeled, %function
pitrex_debug_print_labeled:
    push    {lr}
    mov     r0, r1
    bl      pitrex_print_number
    pop     {pc}

@ pitrex_debug_print_str(r0=str_ptr)
.global pitrex_debug_print_str
.type pitrex_debug_print_str, %function
pitrex_debug_print_str:
    push    {lr}
    mov     r1, r0
    ldr     r0, =-100
    mov     r2, #100
    mov     r3, #1
    mov     r12, #127
    push    {r12}
    bl      v_printStringRaster
    add     sp, sp, #4
    pop     {pc}

@ pitrex_level_collision_y(r0=px, r1=py, r2=hh) -> floor_center_y
.global pitrex_level_collision_y
.type pitrex_level_collision_y, %function
pitrex_level_collision_y:
    push    {r4, r5, r6, r7, r8, r9, r10, lr}
    mov     r4, r0              @ px
    mov     r5, r1              @ py
    mov     r6, r2              @ half_h (player)
    ldr     r7, =LEVEL_DATA_PTR
    ldr     r7, [r7]            @ r7 = level header ptr
    ldr     r10, =-32767        @ best_floor_top sentinel (below any valid Y)
    cmp     r7, #0
    beq     plcy_finish
    ldr     r8, =LEVEL_GP_COUNT
    ldr     r8, [r8]
    cmp     r8, #0
    beq     plcy_finish
    ldr     r9, [r7, #16]       @ r9 = gpObjectsPtr (ROM)
    ldr     r7, =LEVEL_GP_BUF
    sub     r0, r5, r6          @ player_feet = py - hh
plcy_loop:
    cmp     r8, #0
    beq     plcy_finish
    ldrb    r1, [r9, #6]
    tst     r1, #0x10
    beq     plcy_next
    ldrb    r1, [r9, #12]       @ obj half_w
    ldrsh   r2, [r7, #0]        @ obj world_x (buf)
    sub     r2, r4, r2          @ dx = px - obj_x
    movs    r3, r2
    bpl     plcy_dx_ok
    neg     r3, r2
plcy_dx_ok:
    add     r1, r1, #8
    cmp     r3, r1
    bge     plcy_next
    ldrsh   r2, [r7, #2]        @ obj world_y (buf)
    ldrb    r3, [r9, #13]       @ obj half_h
    add     r2, r2, r3          @ obj_top = world_y + half_h
    cmp     r2, r0
    bgt     plcy_next   @ surface above player feet
    cmp     r10, r2
    bge     plcy_next
    mov     r10, r2
plcy_next:
    add     r7, r7, #8
    add     r9, r9, #16
    subs    r8, r8, #1
    b       plcy_loop
plcy_finish:
    ldr     r1, =-32767
    cmp     r10, r1
    beq     plcy_no_floor
    add     r0, r10, r6         @ floor_center = floor_top + player_hh
    pop     {r4, r5, r6, r7, r8, r9, r10, pc}
plcy_no_floor:
    ldr     r0, =-200
    pop     {r4, r5, r6, r7, r8, r9, r10, pc}
    .ltorg

@ pitrex_level_collision_x(r0=px, r1=py, r2=hw, r3=hy) -> push-out dx
.global pitrex_level_collision_x
.type pitrex_level_collision_x, %function
pitrex_level_collision_x:
    push    {r4, r5, r6, r7, r8, r9, r10, r11, lr}
    mov     r4, r0              @ px
    mov     r5, r1              @ py
    mov     r6, r2              @ half_w (player)
    mov     r11, r3             @ half_h (player) — for Y-overlap threshold
    ldr     r7, =LEVEL_DATA_PTR
    ldr     r7, [r7]
    cmp     r7, #0
    beq     plcx_done_zero
    ldr     r8, =LEVEL_GP_COUNT
    ldr     r8, [r8]
    cmp     r8, #0
    beq     plcx_done_zero
    ldr     r9, [r7, #16]       @ gpObjectsPtr (ROM)
    ldr     r7, =LEVEL_GP_BUF
    mov     r10, #0             @ best push-out dx
plcx_loop:
    cmp     r8, #0
    beq     plcx_done
    ldrb    r0, [r9, #6]
    tst     r0, #0x10
    beq     plcx_next
    ldrb    r0, [r9, #13]       @ obj half_h
    ldrsh   r1, [r7, #2]        @ obj world_y
    sub     r1, r5, r1          @ dy = py - obj_y
    movs    r2, r1
    bpl     plcx_dy_ok
    neg     r2, r1
plcx_dy_ok:
    add     r0, r0, r11
    cmp     r2, r0
    bge     plcx_next
    ldrb    r0, [r9, #12]       @ obj half_w
    ldrsh   r1, [r7, #0]        @ obj world_x
    sub     r1, r4, r1          @ dx_raw = px - obj_x
    add     r3, r6, r0          @ total_hw = player_hw + obj_hw
    movs    r2, r1
    bpl     plcx_dx_abs
    neg     r2, r1
plcx_dx_abs:
    cmp     r2, r3
    bge     plcx_next
    sub     r3, r3, r2          @ overlap = total_hw - |dx|
    cmp     r1, #0
    bge     plcx_push_pos
    neg     r3, r3
plcx_push_pos:
    mov     r10, r3
plcx_next:
    add     r7, r7, #8
    add     r9, r9, #16
    subs    r8, r8, #1
    b       plcx_loop
plcx_done:
    mov     r0, r10
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, pc}
plcx_done_zero:
    mov     r0, #0
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, pc}
    .ltorg

