.type pitrex_clamp, %function
pitrex_clamp:
    cmp     r0, r1
    it      lt
    movlt   r0, r1
    cmp     r0, r2
    it      gt
    movgt   r0, r2
    bx      lr

@ pitrex_random() → r0 = pseudo-random i16 in [0, 65535]
.global pitrex_random
.type pitrex_random, %function
pitrex_random:
    ldr     r1, =RAND_SEED
    ldr     r0, [r1]
    ldr     r2, =1664525
    mul     r0, r0, r2
    ldr     r2, =1013904223
    add     r0, r0, r2
    str     r0, [r1]            @ update seed
    lsr     r0, r0, #16         @ use high 16 bits
    uxth    r0, r0
    bx      lr
    .ltorg

