    push    {r4, lr}
    mov     r4, r0
.Lwait_loop:
    cmp     r4, #0
    beq     .Lwait_done
    bl      v_WaitRecal
    sub     r4, r4, #1
    b       .Lwait_loop
.Lwait_done:
    pop     {r4, pc}

@ pitrex_peek(r0=addr) → r0 = byte at that ARM address
